modules.body:
// 1. Declare local signals for our counter
logic clk;
logic rst_n;
logic [3:0] count;

// 2. Counter Logic (triggered on rising edge of clock or falling edge of reset)
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 4'b0000;   // Reset the count to 0
    end else begin
        count <= count + 1;  // Increment the counter
    end
end

// 3. Clock Generator: toggles clk every 5 time units (10 time units period)
initial begin
    clk = 0;
    forever #5 clk = ~clk;
end

// 4. Stimulus and Waveform Generation
initial begin
    // Setup waveform dumping to "waves.vcd" for the visualizer
    $dumpfile("waves.vcd");
    $dumpvars(0, top);

    // Initial inputs
    $display("Starting simulation...");
    rst_n = 0;          // Assert active-low reset (forces count to 0)
    #12;                // Wait 12 time units (mid-clock cycle)

    rst_n = 1;          // Deassert reset (counter starts counting)
    #80;                // Let it run for 80 time units

    rst_n = 0;          // Assert reset again briefly
    #10;

    rst_n = 1;          // Release reset again
    #40;

    $display("Simulation complete! Final count: %d", count);
    $finish;            // Finish the simulation run
end
